import{_ as t,o,c as s,a2 as a}from"./chunks/framework.BXzK3EA4.js";const r="/assets/226_2067fc46-667d-4f49-9647-23c0f5251cd6.CHZii5KA.png",n="/assets/205_blobid4.CkbrEImU.png",g=JSON.parse('{"title":"How to Use Rescue Mode on a Dedicated Server","description":"","frontmatter":{"title":"How to Use Rescue Mode on a Dedicated Server"},"headers":[],"relativePath":"operations-knowledge-base/dedicated-server/how-to-use-rescue-mode-on-a-dedicated-server.md","filePath":"operations-knowledge-base/dedicated-server/how-to-use-rescue-mode-on-a-dedicated-server.md","lastUpdated":1794292919000}'),i={name:"operations-knowledge-base/dedicated-server/how-to-use-rescue-mode-on-a-dedicated-server.md"};function d(c,e,u,l,p,h){return o(),s("div",null,[...e[0]||(e[0]=[a('<h2 id="i-overview" tabindex="-1">I. Overview <a class="header-anchor" href="#i-overview" aria-label="Permalink to &quot;I. Overview&quot;">​</a></h2><p>When a server encounters a failure (for example, the operating system crashes and cannot boot normally) but there is still important data on the disk that needs to be backed up, you can use the <strong>&quot;Rescue system&quot;</strong> feature.</p><p>The rescue system supports both <strong>Linux</strong> and <strong>Windows</strong>. When the system becomes abnormal, the server can be booted into the corresponding rescue mode so you can back up important data.</p><h2 id="ii-access-path" tabindex="-1">II. Access Path <a class="header-anchor" href="#ii-access-path" aria-label="Permalink to &quot;II. Access Path&quot;">​</a></h2><p>Log in to the platform and go to the <strong>&quot;Customer Center&quot;</strong>.</p><p>Under <strong>&quot;My Orders&quot;</strong>, click <strong>&quot;Dedicated&quot;</strong>. Alternatively, go to <strong>&quot;Product Management&quot;</strong>, click <strong>&quot;Dedicated&quot;</strong>, and filter the server list by region and status.</p><p>In the product list, locate the target server and open the <strong>&quot;Product Details&quot;</strong> page.</p><p>Under the <strong>&quot;Server Information&quot;</strong> tab, find and click <strong>&quot;Rescue system&quot;</strong> to open the rescue system window.</p><p><img src="'+r+'" alt=""></p><h2 id="iii-steps" tabindex="-1">III. Steps <a class="header-anchor" href="#iii-steps" aria-label="Permalink to &quot;III. Steps&quot;">​</a></h2><h3 id="_1-select-the-rescue-system-type" tabindex="-1">(1) Select the Rescue System Type <a class="header-anchor" href="#_1-select-the-rescue-system-type" aria-label="Permalink to &quot;(1) Select the Rescue System Type&quot;">​</a></h3><p>In the <strong>&quot;Rescue system&quot;</strong> window, select the rescue system type based on the operating system currently installed on the server:</p><ul><li>If the server is running Linux, select <strong>&quot;Linux&quot;</strong>.</li><li>If the server is running Windows, select <strong>&quot;Windows&quot;</strong>.</li></ul><h3 id="_2-data-backup-operation-example-linux-rescue-mode" tabindex="-1">(2) Data Backup Operation (Example: Linux Rescue Mode) <a class="header-anchor" href="#_2-data-backup-operation-example-linux-rescue-mode" aria-label="Permalink to &quot;(2) Data Backup Operation (Example: Linux Rescue Mode)&quot;">​</a></h3><ol><li>After entering the Linux rescue system, the control panel will automatically display the username and password. Use this information for remote login.</li><li>After logging in, run <code>lsblk</code> or <code>df -Th</code> to check disk partitions and whether they are mounted.</li><li>If the partition is not mounted, mount it manually (for example: <code>mount /dev/sda1 /mnt</code>, which mounts the <code>/dev/sda1</code> partition to the <code>/mnt</code> directory).</li><li>After mounting, check the corresponding partition for any data that needs to be backed up.</li><li>After completing the data backup, you may choose to reinstall the operating system if needed, so you can continue using the server for your business.</li></ol><p><img src="'+n+'" alt=""></p>',16)])])}const f=t(i,[["render",d]]);export{g as __pageData,f as default};
